import os
import random
import numpy as np
import torch


class Config:
    # =========================================================================
    # Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided metadata script
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train_meta.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val_meta.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test_meta.csv")

    # Working directory for artifacts (cache, checkpoints)
    WORK_DIR = "./working/idea_3"
    CACHE_DIR = os.path.join(WORK_DIR, "cache")
    MODEL_SAVE_PATH = os.path.join(WORK_DIR, "best_model.pth")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Configuration
    # =========================================================================
    IMG_SIZE = 640  # Resolution for EfficientNet-B3
    NUM_CLASSES = 14  # 0-13 are findings
    NO_FINDING_CLASS_ID = 14

    # Mapping from Class ID to Class Name
    CLASS_ID_TO_NAME = {
        0: "Aortic enlargement",
        1: "Atelectasis",
        2: "Calcification",
        3: "Cardiomegaly",
        4: "Consolidation",
        5: "ILD",
        6: "Infiltration",
        7: "Lung Opacity",
        8: "Nodule/Mass",
        9: "Other lesion",
        10: "Pleural effusion",
        11: "Pleural thickening",
        12: "Pneumothorax",
        13: "Pulmonary fibrosis",
        14: "No finding",
    }

    # =========================================================================
    # Hyperparameters
    # =========================================================================
    SEED = 42
    BATCH_SIZE = 16  # Fits on A100 with EffNet-B3
    EPOCHS = 20  # Extended schedule for convergence
    LEARNING_RATE = 3e-4
    WEIGHT_DECAY = 1e-4
    NUM_WORKERS = 8  # Efficient data loading

    # Model Architecture Settings
    BACKBONE = "efficientnet_b3"

    # Augmentation
    MIN_VISIBILITY = 0.3  # Ensure objects aren't cropped out significantly

    # Inference / Post-processing
    CONF_THRESHOLD = 0.2  # Confidence threshold for bounding boxes
    IOU_THRESHOLD = 0.4  # IoU threshold for NMS/Metric
    GLOBAL_CLS_THRESHOLD = 0.8  # Threshold for "No finding" global head

    @staticmethod
    def setup():
        """Creates necessary directories for outputs and caching."""
        os.makedirs(Config.WORK_DIR, exist_ok=True)
        os.makedirs(Config.CACHE_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)


def seed_everything(seed=42):
    """Sets the random seed for reproducibility."""
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


# Initialize directories on module import
Config.setup()
